@pytest.mark.asyncio async def test_full_discovery_flow(client): """Test complete discovery flow: service -> entity types -> schemas -> operations."""
# Step 1: Discover service response = await client.get("/api/v1/discovery/") assert response.status_code == 200 service_info = response.json() assert service_info["service"]["name"] == "entity-api"
# Step 2: Create an entity type via DDL entity_type_data = { "entity_type": "product", "description": "Product catalog", "columns": [ {"name": "name", "type": "string", "nullable": False, "max_length": 255}, {"name": "price", "type": "float", "nullable": False}, {"name": "stock", "type": "integer", "nullable": False, "default": 0} ], "created_by": "discovery_test" }
response = await client.post("/api/v1/entity_type", json=entity_type_data) assert response.status_code == 201
# Step 3: Discover entity types response = await client.get("/api/v1/discovery/entity-types") assert response.status_code == 200 entity_types = response.json() assert "product" in entity_types["entity_types"]
# Step 4: Get product schema response = await client.get("/api/v1/discovery/schemas/product") assert response.status_code == 200 schema = response.json() assert schema["entity_type"] == "product" assert "name" in schema["columns"] assert "price" in schema["columns"]
# Step 5: Use discovered endpoint to create entity create_endpoint = schema["endpoints"]["create"] example_data = { "name": "Test Product", "price": 29.99, "stock": 100, "created_by": "discovery_test" }
response = await client.post(create_endpoint, json=example_data) > assert response.status_code == 201 E assert 404 == 201 E + where 404 = <Response [404 Not Found]>.status_code
